export const HM_ICON_FONT_PATH = "/fonts/hm-symbol/HMSymbolVF.ttf";

/**
 * Icon CSS for the sandbox: <span class="hm-icon" data-icon="wifi"></span>
 * renders the HarmonyOS Symbol glyph in currentColor at 24px (1em of the
 * icon's own font-size). fontUrl must be absolute because the sandbox is an
 * opaque-origin srcdoc document.
 */
export function hmIconCss(fontUrl: string): string {
  const glyphs = Object.entries(HM_ICON_CODEPOINTS)
    .map(([name, code]) => `.hm-icon[data-icon="${name}"]::before { content: "\\${code.toString(16)}"; }`)
    .join("\n");
  return `@font-face { font-family: "HM Symbol"; src: url("${fontUrl}") format("truetype"); font-display: block; }
.hm-icon { display: inline-flex; align-items: center; justify-content: center; flex: none; width: 1em; height: 1em; font-size: 24px; line-height: 1; color: inherit; font-family: "HM Symbol"; font-style: normal; font-weight: 400; -webkit-font-smoothing: antialiased; }
.hm-icon.small { font-size: 16px; }
.hm-icon.large { font-size: 32px; }
${glyphs}`;
}
